code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    comp = [[-1]*w for _ in range(h)]
    colors = {}
    k = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or comp[r][c] >= 0:
                continue
            q = deque([(r,c)]); comp[r][c] = k; marks = set()
            while q:
                y,x=q.popleft()
                if grid[y][x] not in (0,1): marks.add(grid[y][x])
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=0 and comp[yy][xx]<0:
                        comp[yy][xx]=k; q.append((yy,xx))
            colors[k]=marks; k+=1
    out=[row[:] for row in grid]
    for r in range(h-2):
        for c in range(w-2):
            cid=comp[r+1][c+1]
            if cid>=0 and all(comp[y][x]==cid for y in range(r,r+3) for x in range(c,c+3)):
                marks=colors[cid]
                if len(marks)==1:
                    out[r+1][c+1]=next(iter(marks))
    return out
'''
